#!/bin/sh
# Print the Homebrew formula for a release.
#
#   scripts/homebrew-formula.sh <version> <sha256sums.txt>
set -eu

version="${1#v}"
sums="$2"
repo="Nexgear75/bcp"

sha() {
    v="$(awk -v f="bcp-$1.tar.gz" '$2 == f { print $1 }' "$sums")"
    [ -n "$v" ] || {
        echo "missing checksum for $1" >&2
        exit 1
    }
    echo "$v"
}

url() { echo "https://github.com/${repo}/releases/download/v${version}/bcp-$1.tar.gz"; }

cat <<RUBY
# Generated by scripts/homebrew-formula.sh in ${repo}: do not edit by hand.
class Bcp < Formula
  desc "Copy and move files with progress bars, atomic writes and data-loss protection"
  homepage "https://github.com/${repo}"
  version "${version}"
  license any_of: ["MIT", "Apache-2.0"]

  on_macos do
    on_arm do
      url "$(url aarch64-apple-darwin)"
      sha256 "$(sha aarch64-apple-darwin)"
    end
    on_intel do
      url "$(url x86_64-apple-darwin)"
      sha256 "$(sha x86_64-apple-darwin)"
    end
  end

  on_linux do
    on_arm do
      url "$(url aarch64-unknown-linux-musl)"
      sha256 "$(sha aarch64-unknown-linux-musl)"
    end
    on_intel do
      url "$(url x86_64-unknown-linux-musl)"
      sha256 "$(sha x86_64-unknown-linux-musl)"
    end
  end

  def install
    bin.install "bcp", "bmv"
    man1.install "man/bcp.1", "man/bmv.1"
    bash_completion.install "completions/bcp.bash" => "bcp", "completions/bmv.bash" => "bmv"
    zsh_completion.install "completions/_bcp", "completions/_bmv"
    fish_completion.install "completions/bcp.fish", "completions/bmv.fish"
  end

  test do
    (testpath/"a.txt").write "hello"
    system bin/"bcp", "--no-progress", "a.txt", "b.txt"
    assert_equal "hello", (testpath/"b.txt").read
    system bin/"bmv", "--no-progress", "b.txt", "c.txt"
    refute_path_exists testpath/"b.txt"
    assert_equal "hello", (testpath/"c.txt").read
    assert_match version.to_s, shell_output("#{bin}/bcp --version")
  end
end
RUBY
